/**
 * Per-locale article loader — GENERATED by scripts/generate-blog-article-chunks.ts.
 * Do NOT edit by hand; re-run the generator (it runs in `npm run build`).
 *
 * One lazy import per generated per-article file
 * (src/locales/<code>/articles/*.ts), so Vite emits one small chunk per
 * article and an article page downloads only its own chunk — never the
 * full locale chunk (audit #6). Mirrors src/registry/blogArticleLoader.ts.
 */

import type { ArticleLocaleOverride } from '../types';

const articleModules = import.meta.glob<{ article: ArticleLocaleOverride; default: ArticleLocaleOverride }>('./articles/*.ts');

/** Article id -> lazy loader, keyed by the filename (<locale>-<id>.ts). */
const loadersById = new Map<string, () => Promise<{ article: ArticleLocaleOverride; default: ArticleLocaleOverride }>>();
for (const [path, loader] of Object.entries(articleModules)) {
  const match = /\/hi-([^/]+)\.ts$/.exec(path);
  if (!match) continue;
  loadersById.set(match[1], loader as () => Promise<{ article: ArticleLocaleOverride; default: ArticleLocaleOverride }>);
}

const articleCache = new Map<string, ArticleLocaleOverride>();

/** Synchronous read of an already-loaded version (null if not loaded yet). */
export function getCachedArticleById(id: string): ArticleLocaleOverride | null {
  return articleCache.get(id) ?? null;
}

export async function loadArticleById(id: string): Promise<ArticleLocaleOverride | null> {
  const cached = articleCache.get(id);
  if (cached) return cached;
  const loader = loadersById.get(id);
  if (!loader) return null;
  try {
    const mod = await loader();
    const version = mod.article ?? mod.default;
    if (!version || typeof version.body !== 'string') return null;
    articleCache.set(id, version);
    return version;
  } catch {
    return null;
  }
}
